/** Vault KPI tiles from the DAL rows (`dvKpis`). */
function vaultKpis(rows: VaultDocument[]) {
  const pending = rows.filter((d) => d.shared && !d.acknowledged).length;
  return [
    [rows.length, `${rows.filter((d) => d.status === 'released').length} released`],
    [rows.filter((d) => d.status === 'release_proposed').length, 'circuit defined by document type'],
    [pending, `${rows.filter((d) => d.shared).length} shared with client`],
    [rows.reduce((s, d) => s + d.withdrawnRevisions, 0), 'automatic on release of the next revision'],
  ];
}
const kpiPairs = (ks: any[]) => ks.map((k) => [k.value, k.sub]);

