describe('prioritisation & capacity (03 §6)', () => {
  it('ranking: the prototype rows (HLT-026 margin 13 % from the contract) + the 3 projects SCORES keyed by obsolete codes', async () => {
    const pf = await getPrioritisation('director', null);
    expect(pf.weights).toEqual([0.25, 0.25, 0.2, 0.15, 0.15]);
    expect(pf.axes.map((a) => a.label)).toEqual(G.prioritisation.weights.map((w: any) => w.l));
    const byCode = new Map(pf.ranking.map((r) => [r.project.code, r]));
    for (const g of G.prioritisation.rows) {
      const r = byCode.get(g.code)!;
      expect([r.score, r.scores, r.marginPct != null ? `${r.marginPct}%` : 'Internal', r.pipeline, r.project.status], g.code)
        .toEqual([g.score, g.axes, g.code === 'HLT-026' ? '13%' : g.marginText, g.isPipeline, g.status]);
    }
    const remapped = { 'EWA-051': 'EWA-041', 'RBR-048': 'RBR-038', 'CER-047': 'CER-045' } as const;
    for (const [code, old] of Object.entries(remapped)) {
      const r = byCode.get(code)!;
      expect(r.scores).toEqual(PROTO.SCORES[old]);
      expect(r.score).toBe(Math.round(priorityScore(PROTO.SCORES[old], pf.weights)));
    }
    expect(pf.ranking.map((r) => r.rank)).toEqual(pf.ranking.map((_, i) => i + 1));
    expect(pf.ranking[0].project.code).toBe('WSA-044');
    expect(pf.ranking.map((r) => r.score)).toEqual([...pf.ranking.map((r) => r.score)].sort((a, b) => b - a));
    // KPI tiles.
    expect([pf.active.length, f(pf.active.reduce((s, p) => s + p.budget, 0)) + ' committed', pf.pipeline.length, f(pf.pipeline.reduce((s, p) => s + p.budget, 0)) + ' proposed · approved · planning', `${Math.round(pf.weightSum * 100)}%`])
      .toEqual([G.prioritisation.kpis[0].value, G.prioritisation.kpis[0].sub, G.prioritisation.kpis[1].value, G.prioritisation.kpis[1].sub, G.prioritisation.kpis[4].value]);
  });

  /**
   * A-12 (chapter 4): capacity = pool members × 40 h × 8 weeks, committed = Σ pool loads × 40 h (allocations), demand per
   * €1M = committed ÷ active portfolio value (contract, else budget: €14.85M) — the prototype's capBase and coefficients
   * gave Engineering 960 h / 1 110 h / 140 h per €1M. Per department: [capacity, committed, candidate add].
   */
  const POOL: [number, number][] = [[320, 318], [640, 532], [320, 314], [960, 716], [320, 252]];
  const ADD: Record<string, number[]> = {
    'WSA-044': [73, 122, 72, 164, 58], 'EWA-051': [47, 79, 47, 106, 37], 'FTU-052': [10, 17, 10, 23, 8], 'RBR-048': [109, 183, 108, 246, 87], 'CER-047': [41, 68, 40, 92, 32],
  };
  it.each(['WSA-044', 'EWA-051', 'FTU-052', 'RBR-048', 'CER-047'])('capacity what-if of %s', async (code) => {
    const g = G.prioritisation.capacity[code];
    const w = (await getCapacityWhatIf(code))!;
    const rows = g.rows.map((r: any, i: number) => {
      const [cap, cur] = POOL[i];
      const add = ADD[code][i];
      return { name: r.name, cap, cur, add, tot: cur + add, gap: Math.max(0, cur + add - cap) };
    });
    expect(w.departments.map((d) => ({ name: d.department, cap: d.capacityH, cur: d.committedH, add: d.addH, tot: d.totalH, gap: d.gapH }))).toEqual(rows);
    expect(w.gapH).toBe(rows.reduce((s: number, r: any) => s + r.gap, 0));
    expect(w.gapH).not.toBe(Number(g.wi.gapText.split(' ')[0]));
  });
});

// ── Meetings ───────────────────────────────────────────────────────────────────────────────────────────

const ORDER = { notes_in_progress: 0, scheduled: 1, minutes_sent: 2 } as const;
const overdueDue = (due: string | null) => !!due && due !== '—' && monthIndexOfIso(`2026-${String(['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'].indexOf(due.split(' ')[1]) + 1).padStart(2, '0')}-${due.split(' ')[0].padStart(2, '0')}`) < PG_NOW;

describe('meetings & minutes (05 §5)', () => {
  it.each(['HLT-026', 'NDC-031', 'EWA-051'])('%s: list, KPIs, actions and decisions registers', async (code) => {
    const g = G.meetings[code];
    const ms = await listMeetings(code);
    const list = [...ms].sort((a, b) => ORDER[a.status] - ORDER[b.status] || b.monthIndex - a.monthIndex);
    expect(list.map((m) => ({
      id: m.number, title: m.title, status: m.statusLabel, type: m.typeLabel, date: m.dateText, time: m.time, dur: m.durationText, loc: m.location, organizer: m.organizer,
      sub: `${m.dateText} · ${m.time} · ${m.participants.length} invited${m.actionCount ? ` · ${m.actionCount} actions` : ''}`, doc: m.minutesNumber ?? '',
    }))).toEqual(g.list);
    const lines = ms.flatMap((m) => m.agenda.flatMap((a) => a.lines.map((l) => ({ m, l }))));
    const actions = lines.filter((x) => x.l.type === 'action');
    const decisions = lines.filter((x) => x.l.type === 'decision');
    expect([
      ms.filter((m) => Math.abs(m.monthIndex - PG_NOW) <= 0.25).length, `${ms.filter((m) => m.status === 'scheduled').length} upcoming`,
      ms.filter((m) => m.status === 'notes_in_progress').length,
      actions.filter((x) => !x.l.done).length, `${actions.filter((x) => x.l.overdue).length} overdue`,
      decisions.filter((x) => x.m.monthIndex >= 8).length, `${decisions.filter((x) => x.m.type === 'external').length} with the client`,
    ]).toEqual([g.kpis[0].value, g.kpis[0].sub, g.kpis[1].value, g.kpis[2].value, g.kpis[2].sub, g.kpis[3].value, g.kpis[3].sub]);
    expect([...actions].sort((a, b) => Number(a.l.done) - Number(b.l.done)).map(({ m, l }) => ({
      mid: m.number, text: l.text, owner: l.owner, ownerFull: l.ownerFull, due: l.due, done: l.done, stText: l.done ? 'Done' : l.overdue ? 'Overdue' : 'Open',
    }))).toEqual(g.actions);
    expect(actions.every(({ l }) => l.overdue === (!l.done && overdueDue(l.due)))).toBe(true);
    expect([...decisions].sort((a, b) => b.m.monthIndex - a.m.monthIndex).map(({ m, l }) => ({ mid: m.number, text: l.text, pt: m.agenda[l.point].title, mtype: m.typeLabel }))).toEqual(g.decisions);
  });

  it('every meeting: meta, attendance, agenda lines, carry-over, distribution, preparation pack, transcript analysis', async () => {
    for (const code of ['HLT-026', 'NDC-031']) {
      const ms = await listMeetings(code);
      const questions = await listClientQuestions(code);
      for (const m of ms) {
        const g = G.meetings[code].detail[m.number];
        expect(`${m.dateText} · ${m.time} · ${m.durationText} · ${m.location}`).toBe(g.meta);
        expect(m.participants.map((p) => ({ name: p.name, present: p.present, label: p.name + (m.status !== 'scheduled' && !p.present ? ' · absent' : '') }))).toEqual(g.attendance);
        expect(m.agenda.map((a) => ({ pt: a.title, lines: a.lines.map((l) => ({ type: l.type, text: l.text, owner: l.owner ?? '', due: l.due ?? '', done: l.done })) }))).toEqual(g.agenda);
        const prevSame = ms.filter((x) => x.series === m.series && x.number !== m.number && x.monthIndex < m.monthIndex).sort((a, b) => b.monthIndex - a.monthIndex)[0];
        const carried = prevSame ? prevSame.agenda.flatMap((a) => a.lines).filter((l) => l.type === 'action' && !l.done).map((l) => ({ text: l.text, owner: l.owner, due: l.due, from: `${prevSame.number} · ${prevSame.dateText}` })) : [];
        expect(carried).toEqual(g.carried);
        expect(m.minutesSentOn ? `Sent ${m.sentText} · ${m.minutesNumber}` : '').toBe(g.sentText);
        expect(m.participants.filter((p) => p.minutesRecipient).map((p) => ({ who: p.name, state: p.readOn ? `Read ${p.readText}` : 'Not read yet' }))).toEqual(g.dist);
        if (m.status === 'minutes_sent') {
          expect(g.prep).toBeNull();
          continue;
        }
        const prev = ms.filter((x) => x.series === m.series && x.status === 'minutes_sent' && x.number !== m.number).sort((a, b) => b.monthIndex - a.monthIndex)[0];
        const prevLines = prev ? prev.agenda.flatMap((a) => a.lines) : [];
        const internal = m.type === 'internal';
        const bridge = questions.map((q) => ({
          text: q.text, sub: (internal ? `Client question · ${q.askedBy}` : `Answer from ${q.department}`) + ` · ${q.owner}`, label: q.state === 'answered' ? 'Answer ready' : 'Needs an answer',
          hasAnswer: !!q.answer, answer: q.answer ?? '',
        })).filter((q) => internal || q.hasAnswer);
        expect({
          prevRef: prev ? `${prev.title} · ${prev.dateText}` : '', prevDecisions: prevLines.filter((l) => l.type === 'decision').map((l) => ({ text: l.text })),
          closedCount: `${prevLines.filter((l) => l.type === 'action' && l.done).length} / ${prevLines.filter((l) => l.type === 'action').length}`,
          bridge, bridgeTitle: internal ? 'From the client meeting — questions to prepare' : 'From the internal meeting — answers to bring to the client', transcript: m.transcript?.text ?? '',
        }).toEqual({ ...g.prep, bridge: g.prep.bridge.map((q: any) => without(q, 'tagClass')) });
        expect(prevLines.filter((l) => l.type === 'action').map((l) => ({ text: l.text, who: l.owner, due: l.due, done: l.done }))).toEqual(g.prevActions);
        if (m.transcript) {
          expect(m.transcript.analysed).toBe(false);
          expect(m.transcript.summary).toBeNull();
        }
      }
    }
  });

  it('meetings badge (notes in progress) and the analysed transcripts once revealed (seed state: not analysed)', async () => {
    expect(await meetingsToWriteByProject()).toEqual({ 'HLT-026': 1, 'NDC-031': 1 });
    const ms: MeetingRow[] = [...(await listMeetings('HLT-026')), ...(await listMeetings('NDC-031'))];
    expect(ms.filter((m) => m.transcript).map((m) => m.number).sort()).toEqual(['MTG-119', 'MTG-120', 'MTG-121']);
    expect(ms.find((m) => m.number === 'MTG-117')).toMatchObject({ minutesNumber: 'MIN-HLT-023', minutesIndexed: true });
    expect(ms.find((m) => m.number === 'MTG-116')).toMatchObject({ minutesNumber: 'MIN-HLT-022', minutesIndexed: false });
  });
});

// ── Stakeholders, interfaces ───────────────────────────────────────────────────────────────────────────

describe('stakeholders & RACI (05 §6)', () => {
  it('register, KPI tiles and RACI matrix', async () => {
    const { stakeholders: rows, raci } = await getStakeholderRegister('HLT-026');
    expect(rows.map((r) => ({
      name: r.name, org: r.organisation, role: r.role, type: r.typeLabel, contactText: r.contactEmail ?? '—', owner: r.owner, last: r.lastText,
      lastText: r.lastText + (r.stale ? ' · > 30 d' : ''), notes: r.notes, initials: r.initials,
    }))).toEqual(G.stakeholders.rows);
    const owners = [...new Set(rows.map((r) => r.owner))];
    expect([
      rows.length, `${rows.filter((r) => r.type === 'client').length} client · ${rows.filter((r) => r.type === 'authority').length} authorities · ${rows.filter((r) => r.type === 'supplier' || r.type === 'third_party').length} suppliers & third parties`,
      owners.length, owners.join(' · '), raci!.rows.length, `${raci!.columns.length} roles`, rows.filter((r) => r.stale).length,
    ]).toEqual([G.stakeholders.kpis[0].value, G.stakeholders.kpis[0].sub, G.stakeholders.kpis[1].value, G.stakeholders.kpis[1].sub, G.stakeholders.kpis[2].value, G.stakeholders.kpis[2].sub, G.stakeholders.kpis[3].value]);
    expect(raci!.columns).toEqual(G.stakeholders.cols);
    expect(raci!.rows.map((r) => [r.label, ...r.cells.map((c) => c ?? '')])).toEqual(G.stakeholders.raci);
    expect(await getStakeholderRegister('EWA-051')).toEqual({ stakeholders: [], raci: null });
  });
});

describe('interface register (07 §2.5)', () => {
  it('rows (late derived, days to need), KPI tiles and badge', async () => {
    const rows = await listInterfaces('HLT-026');
    expect(rows.map((r) => ({
      id: r.number, title: r.title, a: r.keystoneSideLabel, b: r.otherParty, data: r.dataExpected, needed: r.neededText, provided: r.providedText, status: r.statusLabel, owner: r.owner,
      neededSub: r.status === 'late' ? `${Math.abs(r.daysToNeed)} d late` : r.status === 'open' ? `in ${r.daysToNeed} d` : '',
    }))).toEqual(G.interfaces.rows);
    const blocking = rows.filter((r) => ['IF-02', 'IF-05'].includes(r.number) && r.status !== 'frozen' && r.status !== 'received');
    expect([
      rows.length, `${rows.filter((r) => r.status === 'frozen').length} frozen · ${rows.filter((r) => r.status === 'received').length} received`,
      rows.filter((r) => r.status === 'open').length, `${rows.filter((r) => r.status === 'open' && r.daysToNeed >= 0).length} due within 30 days`,
      rows.filter((r) => r.status === 'late').length, rows.filter((r) => r.status === 'late').map((r) => r.number).join(' · ') || '—', blocking.length,
    ]).toEqual([G.interfaces.kpis[0].value, G.interfaces.kpis[0].sub, G.interfaces.kpis[1].value, G.interfaces.kpis[1].sub, G.interfaces.kpis[2].value, G.interfaces.kpis[2].sub, G.interfaces.kpis[3].value]);
    expect(await lateInterfacesByProject()).toEqual({ 'HLT-026': 1 });
    expect(await listInterfaces('EWA-051')).toEqual([]);
  });
});

// ── Portfolio schedule, Projects map ───────────────────────────────────────────────────────────────────

const pgPct = (m: number) => ((Math.max(0, Math.min(PG_MONTHS, m)) / PG_MONTHS) * 100).toFixed(2) + '%';
const pgSeg = (a: number, b: number) => {
  const L = Math.max(0, a);
  const R = Math.min(PG_MONTHS, b);
  return R > L ? { left: pgPct(L), width: (((R - L) / PG_MONTHS) * 100).toFixed(2) + '%', w: R - L } : null;
};

describe('portfolio schedule (05 §3)', () => {
  it.each([null, 'euna', 'afr', 'apac'] as const)('zone %s: rows, stage windows, boards, execution bars, gates and KPI tiles', async (zone) => {
    const g = G.pfplan[String(zone)];
    const ps = await getPortfolioSchedule(zone);
    const rows = ps.rows.map((r) => {
      const segs: any[] = [];
      for (const w of r.windows) {
        const s = pgSeg(w.start, w.end);
        if (!s) continue;
        const isB = w.window === 'board';
        const title = isB ? `Group board · ${w.board === 'approved' ? 'Approved' : w.board === 'pending' ? 'Decision pending' : 'Planned'}` : w.label;
        segs.push({ left: s.left, width: s.width, title, label: !isB && s.w > 0.8 ? (w.window === 'initiative' ? 'INI' : w.label) : '' });
        if (isB) segs.push({ left: pgPct(w.end), width: '0', title, diamond: true });
      }
      const ind = r.pipeline ? null : projectIndicators(r.project, r.schedule, true, 'en');
      const slipM = ind && ind.floatDays != null && ind.floatDays < 0 ? -ind.floatDays / 30 : 0;
      const base = r.finishMonth ?? (r.pipeline ? r.execStart + 8 : Math.max(r.execStart + 1, PG_NOW));
      const fc = r.finishMonth != null || r.pipeline ? base + slipM : base;
      const exec = pgSeg(r.execStart, fc);
      const execBase = pgSeg(r.execStart, base);
      const pending = r.windows.find((w) => w.board === 'pending');
      const nextB = r.windows.find((w) => w.window === 'board' && w.end > PG_NOW);
      const nextStage = nextB ? (r.windows[r.windows.indexOf(nextB) + 1]?.label ?? 'Execution') : '';
      const wait = pending ? Math.round((PG_NOW - pending.start) * 30) : 0;
      return {
        code: r.project.code, pipe: r.pipeline,
        gate: r.pipeline ? (nextB ? `Group board → ${nextStage}` : '—') : r.finishMonth == null ? 'finish not planned' : ind!.finishForecast,
        gateSub: r.pipeline ? (pending ? `Decision pending · ${wait} d` : nextB ? fmtD(monthDate(nextB.end)) : '') : r.finishMonth == null ? '' : ind!.floatText !== '—' ? ind!.floatText : '',
        hasExec: !!exec, exL: exec?.left ?? '0', exW: exec?.width ?? '0', exFill: r.pipeline ? '0%' : `${Math.round(r.project.progress * 100)}%`,
        hasBase: !r.pipeline && !!execBase && slipM > 0 && r.finishMonth != null, clipped: fc > PG_MONTHS, segs,
      };
    });
    const want = g.groups.flatMap((gr: any) => gr.rows).map((r: any) => ({
      code: r.code, pipe: r.pipe, gate: r.gate, gateSub: r.gateSub, hasExec: r.hasExec, exL: r.exL, exW: r.exW,
      exFill: r.exFill, hasBase: r.hasBase, clipped: r.clipped, segs: r.segs,
    }));
    const order = (xs: any[]) => [...xs.filter((x) => !x.pipe), ...xs.filter((x) => x.pipe)];
    expect(order(rows)).toEqual(want);
    expect(ps.averageBoardWaitDays + ' d').toBe(g.kpis[3].value);
    const pend = rows.filter((r) => r.gateSub.startsWith('Decision pending')).map((r) => r.code);
    expect([rows.filter((r) => !r.pipe).length, rows.filter((r) => r.pipe).length, pend.length, pend.join(' · ') || '—']).toEqual([g.kpis[0].value, g.kpis[1].value, g.kpis[2].value, g.kpis[2].sub]);
  });
});

describe('projects map (03 §3)', () => {
  it.each([null, 'euna', 'afr', 'apac'] as const)('zone %s: points, categories, site groups, KPI tiles and frame', async (zone) => {
    const g = G.map[String(zone)];
    const m = await getProjectsMap(zone);
    expect(m.points.map((p) => ({
      code: p.project.code, city: p.city, country: p.country, lat: p.lat, lng: p.lng, cat: p.category, health: p.health ? healthLabel(p.health) : '', status: p.project.status,
      client: p.project.client, pm: p.project.pm,
    }))).toEqual(g.points.map((p: any) => without(p, 'name')));
    expect(m.groups.map((x) => ({ city: x.city, country: x.country, codes: x.points.map((p) => p.project.code) }))).toEqual(g.groups);
    const risk = m.points.filter((p) => p.health && p.health !== 'on_track');
    expect([
      m.points.length, m.unlocated ? `${m.unlocated} without location` : (m.zone?.label ?? 'Whole portfolio'), m.groups.length, `${m.countries.length} ${m.countries.length === 1 ? 'country' : 'countries'}`,
      m.points.filter((p) => p.category === 'active').length, `${m.points.filter((p) => p.category === 'pipeline').length} in pipeline`, risk.length,
      `${m.points.filter((p) => p.health === 'off_track').length} off track`,
    ]).toEqual(g.kpis.flatMap((k: any) => [k.value, k.sub]));
    expect(m.zone ? { label: m.zone.label, bounds: m.zone.bounds } : null).toEqual(g.zone);
  });
});

describe('time model helpers', () => {
  it('PG_NOW comparisons match the prototype mIdx', () => {
    expect(monthIndexOfIso('2026-12-14')).toBeCloseTo(11 + 13 / 30);
    expect(monthIndexOfIso('2026-09-30') < PG_NOW).toBe(true);
    expect(monthIndexOfIso('2026-10-01') < PG_NOW).toBe(false);
    expect(addDaysIso('2026-09-26', 45)).toBe('2026-11-10');
  });
});
